*{box-sizing:border-box} :root{--ink:#f7f3ff;--muted:#a19aac;--line:rgba(255,255,255,.1);--panel:rgba(24,20,37,.88);--orange:#ff8c43;--gold:#ffcf74;--violet:#a887ff}html,body{margin:0;min-height:100%;background:#100d1c;color:var(--ink);font-family:'DM Sans',sans-serif}body{min-height:100vh;background:radial-gradient(ellipse at 78% 12%,rgba(107,67,168,.19),transparent 40%),radial-gradient(ellipse at 14% 56%,rgba(189,78,59,.11),transparent 36%),#100d1c}button{font:inherit;color:inherit;cursor:pointer}.app-shell{width:min(1280px,100%);margin:0 auto;padding:0 40px;min-height:100vh;position:relative}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:3}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink);font-family:'Barlow Condensed',sans-serif;font-size:23px;font-weight:900;letter-spacing:1.6px;line-height:.85}.brand-mark{width:37px;height:37px;display:grid;place-items:center;background:linear-gradient(145deg,#ffd48a,#fa7349);color:#241527;font-size:24px;clip-path:polygon(15% 0,100% 0,85% 100%,0 100%);font-style:italic}.brand-sub{display:block;color:#9f96aa;font:600 8px 'DM Sans',sans-serif;letter-spacing:2px;margin-top:6px}.top-right{display:flex;align-items:center;gap:9px;color:#b9b1c3;font-size:10px;font-weight:700;letter-spacing:1.5px}.status-dot{width:6px;height:6px;border-radius:50%;background:#73e8ac;box-shadow:0 0 10px #73e8ac}.sound-button{margin-left:22px;border:1px solid var(--line);background:rgba(255,255,255,.04);border-radius:4px;padding:8px 11px;font-size:13px}.sound-button span{font-size:9px;letter-spacing:1px;margin-left:5px}.setup-screen{padding:34px 0 18px}.hero-copy{margin-bottom:28px}.eyebrow{font-size:9px;font-weight:700;letter-spacing:2px;color:#aaa1b7}.hero-copy .eyebrow{color:#e8aa77;display:flex;gap:9px;align-items:center}.hero-copy .eyebrow i{width:23px;height:1px;background:#d18b66}.hero-copy h1{font:900 clamp(42px,5vw,63px)/.86 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:15px 0 12px}.hero-copy h1 em{font-style:normal;color:var(--gold);text-shadow:0 4px 30px rgba(255,188,100,.12)}.hero-copy p{font-size:12px;line-height:1.7;color:#aaa3b3;margin:0}.setup-grid{display:grid;grid-template-columns:1.07fr .93fr;gap:16px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:7px;box-shadow:0 16px 50px #08071050;position:relative;overflow:hidden}.fighter-panel,.match-panel{padding:20px}.section-heading{display:flex;justify-content:space-between;align-items:center}.section-heading h2{font:700 19px 'Barlow Condensed',sans-serif;letter-spacing:.8px;margin:4px 0 0}.roster-count{font:600 10px 'DM Sans',sans-serif;color:#777181}.roster{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:16px 0 14px}.fighter-card{height:132px;border:1px solid rgba(255,255,255,.1);background:linear-gradient(160deg,rgba(255,255,255,.07),rgba(255,255,255,.015));border-radius:5px;position:relative;overflow:hidden;padding:0;text-align:left;transition:.18s transform,.18s border-color}.fighter-card:hover{transform:translateY(-3px);border-color:#e4a77a}.fighter-card.selected{border:1px solid #ffc178;box-shadow:inset 0 0 24px rgba(255,162,94,.12)}.fighter-card canvas{width:100%;height:100%;display:block}.fighter-card-name{position:absolute;bottom:7px;left:8px;font:700 12px 'Barlow Condensed',sans-serif;letter-spacing:.7px;text-shadow:0 2px 6px #000}.fighter-card-num{position:absolute;right:7px;top:7px;color:#d4c6cf;font-size:8px;letter-spacing:1px}.selected-info{min-height:85px;border-top:1px solid var(--line);padding-top:13px;display:grid;grid-template-columns:60px 1fr auto;align-items:center;gap:11px}.selected-portrait{height:64px;width:60px;border-radius:4px;background:linear-gradient(145deg,#47304b,#1d1828);overflow:hidden}.selected-portrait canvas{width:100%;height:100%}.selected-info h3{font:800 21px 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:2px 0}.selected-info p{font-size:9px;color:#aaa1b2;margin:0;line-height:1.4}.selected-info .eyebrow{font-size:7px;letter-spacing:1.2px;color:#d4a47f}.stat-list{width:88px;display:grid;gap:5px}.stat-row{font-size:8px;color:#a49aaa;display:grid;grid-template-columns:27px 1fr;align-items:center}.stat-track{height:3px;background:#37303f}.stat-track i{height:100%;display:block;background:linear-gradient(90deg,#d67e63,#ffd17c)}.spark{color:#ffc57c;font-size:19px}.opponent-card{height:127px;margin:15px 0 16px;border:1px solid rgba(255,255,255,.1);border-radius:5px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 75% 55%,#784b50 0,#342638 36%,#211b2c 80%)}.opponent-glow{position:absolute;width:135px;height:135px;border-radius:50%;right:25px;top:-6px;background:#f2a0601c;filter:blur(16px)}.opponent-art{position:absolute;inset:0}.opponent-art canvas{position:absolute;height:155px;width:155px;right:20px;bottom:-16px}.opponent-label{position:absolute;left:15px;bottom:15px;display:grid;gap:2px}.opponent-label strong{font:800 27px/.9 'Barlow Condensed',sans-serif;letter-spacing:1px}.opponent-label small{font-size:8px;letter-spacing:1.3px;color:#d1a183}.swap-button{position:absolute;right:11px;top:10px;border:1px solid #ffffff36;background:#160f2080;width:28px;height:28px;border-radius:50%;font-size:17px;color:#ffd299}.difficulty-label{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.difficulty-label>span:last-child{font-size:9px;color:#82798c}.difficulty-options{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.difficulty-options button{height:35px;background:#ffffff06;border:1px solid var(--line);border-radius:3px;color:#a9a0b0;font-size:9px;font-weight:700;letter-spacing:.8px}.difficulty-options button span{font-size:8px;color:#6e6678;margin-right:5px}.difficulty-options button.active{border-color:#d99469;background:rgba(211,133,96,.12);color:#f4c18a}.difficulty-options button.active span{color:#df9c6d}.start-button{margin-top:16px;width:100%;height:44px;border:0;border-radius:3px;background:linear-gradient(100deg,#efa965,#ffd58c);color:#241625;font:800 12px 'DM Sans',sans-serif;letter-spacing:1.3px;display:flex;align-items:center;justify-content:center;position:relative;box-shadow:0 5px 20px #ec9c5730}.start-button b{position:absolute;right:17px;font-size:20px;font-weight:500;top:9px}.start-button:hover{filter:brightness(1.09);transform:translateY(-1px)}.control-note{text-align:center;color:#81798c;font-size:7px;letter-spacing:1.4px;margin-top:10px}.setup-footer{display:flex;justify-content:space-between;color:#625b6b;font-size:8px;letter-spacing:1.5px;margin:17px 2px}.hidden{display:none!important}.game-screen{padding:16px 0 16px}.arena-top{height:36px;display:flex;justify-content:space-between;align-items:flex-start;color:#aaa2b1}.back-button{border:0;background:none;color:#c5bdcb;font-size:15px;padding:5px 0}.back-button span{font-size:9px;letter-spacing:1px;margin-left:4px}.round-label{text-align:center;font-size:8px;line-height:1.2;letter-spacing:1.3px;color:#8e8596}.round-label b{color:#eed9bd}.round-number{font-size:9px;letter-spacing:1.3px}.round-number b{font:700 17px 'Barlow Condensed',sans-serif;color:#f5c27c;margin-left:4px}.battle-hud{height:66px;display:grid;grid-template-columns:1fr 70px 1fr;gap:20px;align-items:center;position:relative;z-index:2}.combatant-line{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.combatant-line strong{font:800 20px 'Barlow Condensed',sans-serif;letter-spacing:1px}.combatant-line span{font-size:8px;letter-spacing:1px;color:#c1b6c7}.health-track{height:12px;background:#372530;border:1px solid #63414b;clip-path:polygon(0 0,100% 0,98% 100%,0 100%)}.enemy-hud .health-track{clip-path:polygon(2% 0,100% 0,100% 100%,0 100%)}.health-fill{height:100%;width:100%;transition:width .2s;background:linear-gradient(90deg,#ef8c63,#ffd787);box-shadow:0 0 10px #f0985b80}.enemy-health{margin-left:auto;background:linear-gradient(90deg,#dc5f64,#ffb074)}.energy-track{margin-top:4px;height:4px;background:#282338}.energy-fill{height:100%;width:35%;background:linear-gradient(90deg,#7065ec,#b39aff);transition:width .2s}.enemy-energy{margin-left:auto;background:#db75d9}.timer{text-align:center;align-self:center;color:#ffe0a6;font:800 34px/.9 'Barlow Condensed',sans-serif}.timer small{display:block;font:600 7px 'DM Sans',sans-serif;letter-spacing:2px;color:#8c8496;margin-top:4px}.arena-wrap{position:relative;height:min(54vh,470px);min-height:270px;border:1px solid #d6aa7c35;border-radius:5px;overflow:hidden;background:#17172c;box-shadow:0 10px 40px #06050c7a}.arena-wrap:before{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,transparent 58%,rgba(12,10,19,.78)),radial-gradient(ellipse at 50% 100%,#e8804f37,transparent 52%);z-index:1}.arena-wrap canvas{width:100%;height:100%;display:block}.arena-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 100px #0e0b1c70;z-index:2}.announce{position:absolute;z-index:4;left:50%;top:44%;transform:translate(-50%,-50%);font:900 clamp(34px,6vw,65px) 'Barlow Condensed',sans-serif;letter-spacing:5px;color:#ffe2ae;text-shadow:0 4px 26px #fb945b;opacity:0;pointer-events:none;white-space:nowrap}.announce.show{animation:announce 1.15s ease-out}@keyframes announce{0%{opacity:0;transform:translate(-50%,-35%) scale(.7)}25%{opacity:1;transform:translate(-50%,-50%) scale(1.12)}70%{opacity:1}100%{opacity:0;transform:translate(-50%,-65%) scale(1.04)}}.battle-bottom{height:24px;display:flex;align-items:center;justify-content:space-between}.arena-tip{font-size:8px;letter-spacing:1.5px;color:#948a9d}.combo-readout{font:800 14px 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#ffd184}.touch-controls{display:flex;justify-content:space-between;align-items:flex-end;margin-top:1px;user-select:none;-webkit-user-select:none;touch-action:none}.move-pad,.action-pad{display:flex;align-items:center;gap:8px}.move-pad button,.action-pad button{height:56px;min-width:57px;border-radius:50%;border:1px solid #ffffff25;background:linear-gradient(145deg,#393044d9,#1c1826e8);box-shadow:0 3px 15px #08070b80;color:#f1e8f0;font-weight:700;touch-action:none}.move-pad button{font-size:17px;color:#e8cdb5}.action-pad button{height:48px;min-width:52px;font-size:16px}.action-pad button span{display:block;font-size:7px;letter-spacing:.6px;margin-top:3px}.action-pad .attack-action{height:66px;min-width:66px;background:linear-gradient(145deg,#e77e59,#ab4053);border-color:#ffb07a66}.action-pad .blast-action{background:linear-gradient(145deg,#6454c3,#382e75)}.action-pad .block-action{background:linear-gradient(145deg,#416f9d,#2d3e6c)}.keyboard-hint{text-align:center;color:#706979;font-size:8px;letter-spacing:1.4px;margin-top:12px}.keyboard-hint span{color:#d39468;padding:0 6px}.result-modal{position:fixed;inset:0;z-index:10;background:#080711c9;display:grid;place-items:center;padding:20px;backdrop-filter:blur(8px)}.result-card{width:min(430px,100%);padding:38px 25px;background:linear-gradient(145deg,#30253a,#171321);border:1px solid #e8ad7855;border-radius:8px;text-align:center;box-shadow:0 20px 70px #0009}.result-card h2{font:900 57px/.9 'Barlow Condensed',sans-serif;color:#ffd28a;margin:15px 0 10px}.result-card p{color:#b7aebc;font-size:12px}.result-actions{display:flex;gap:9px;margin-top:25px}.result-actions button{flex:1;height:42px;border:1px solid #e6a76c;background:#e6a76c;color:#271a25;border-radius:3px;font-size:10px;font-weight:800;letter-spacing:.7px}.result-actions button+button{background:transparent;color:#e6c5a6;border-color:#ffffff30}.mobile-only{display:none}
@media(min-width:1000px){.setup-screen{padding-top:45px}.hero-copy{margin-bottom:31px}.fighter-panel,.match-panel{padding:24px}.roster{margin-top:20px;gap:11px}.fighter-card{height:150px}.selected-info{padding-top:16px}.opponent-card{height:143px}.game-screen{max-width:1000px;margin:0 auto}.arena-wrap{height:min(57vh,510px)}}
@media(max-width:700px){.app-shell{padding:0 16px}.topbar{height:60px}.brand{font-size:19px}.brand-mark{width:32px;height:32px}.top-right{font-size:8px;letter-spacing:1px}.sound-button{margin-left:8px;padding:7px}.sound-button span{display:none}.setup-screen{padding-top:24px}.hero-copy{margin-bottom:21px}.hero-copy h1{font-size:48px;margin:13px 0 9px}.hero-copy p{font-size:11px}.setup-grid{grid-template-columns:1fr;gap:12px}.fighter-panel,.match-panel{padding:15px}.section-heading h2{font-size:17px}.roster{gap:6px;margin:13px 0 11px}.fighter-card{height:112px}.fighter-card-name{font-size:11px;left:6px}.selected-info{grid-template-columns:53px 1fr 77px;gap:8px;min-height:75px}.selected-portrait{width:53px;height:58px}.selected-info h3{font-size:19px}.selected-info p{font-size:8px}.stat-list{width:77px}.stat-row{font-size:7px}.opponent-card{height:105px;margin:12px 0}.opponent-art canvas{height:137px;width:137px;right:8px}.opponent-label{left:12px;bottom:12px}.opponent-label strong{font-size:24px}.setup-footer{font-size:7px;margin:14px 0}.difficulty-options button{height:33px}.start-button{margin-top:12px;height:42px}.game-screen{padding-top:11px;min-height:calc(100dvh - 60px);display:flex;flex-direction:column}.arena-top{height:31px;flex-shrink:0}.battle-hud{height:59px;gap:9px;grid-template-columns:1fr 48px 1fr;flex-shrink:0}.combatant-line strong{font-size:16px}.combatant-line span{font-size:7px}.health-track{height:10px}.timer{font-size:29px}.arena-wrap{height: min(45vh,390px);min-height:235px;flex-shrink:1}.battle-bottom{height:21px;flex-shrink:0}.arena-tip{font-size:7px;letter-spacing:1px}.touch-controls{margin-top:auto;padding-bottom:max(4px,env(safe-area-inset-bottom));padding-top:8px}.move-pad,.action-pad{gap:5px}.move-pad button{min-width:50px;height:50px}.action-pad button{min-width:43px;height:45px}.action-pad .attack-action{min-width:56px;height:59px}.action-pad button span{font-size:6px}.keyboard-hint{margin:8px 0 max(4px,env(safe-area-inset-bottom));font-size:7px}.desktop-only{display:none}}
@media(max-width:380px){.app-shell{padding:0 11px}.fighter-card{height:96px}.fighter-panel,.match-panel{padding:12px}.hero-copy h1{font-size:43px}.move-pad button{min-width:44px;height:46px}.action-pad{gap:4px}.action-pad button{min-width:39px;height:42px}.action-pad .attack-action{min-width:52px;height:55px}.action-pad .attack-action span,.action-pad button span{font-size:5px}}
@media(orientation:landscape) and (max-height:520px){.topbar{height:46px}.app-shell{padding:0 22px}.game-screen{padding-top:7px}.arena-top{height:24px}.battle-hud{height:48px}.arena-wrap{height:calc(100dvh - 200px);min-height:170px}.touch-controls{position:absolute;left:22px;right:22px;bottom:7px;margin:0;z-index:5;pointer-events:none}.touch-controls button{pointer-events:auto}.keyboard-hint{margin-top:6px}.battle-bottom{height:20px}.setup-screen{padding-top:20px}}

(() => {
  'use strict';
  const roster = [
    {name:'KAIRO', title:"EARTH'S LAST HOPE", desc:'A fearless martial artist with limitless potential.', colors:['#ef8b47','#ffe0a6','#40317b'], stats:[8,7,9], hair:'#271b28', aura:'#ffae55'},
    {name:'VEGA', title:'THE PRINCE OF RUIN', desc:'An elite warrior who never backs down from a challenge.', colors:['#5866ad','#e7d9c9','#ad4f69'], hair:'#25243a', aura:'#9b8cff'},
    {name:'NOVA', title:'THE COSMIC PRODIGY', desc:'A playful genius whose power keeps evolving.', colors:['#43a99b','#ffd77b','#4a5695'], hair:'#352748', aura:'#69f5d1'},
    {name:'ROHAN', title:'THE UNSTOPPABLE', desc:'A gentle giant with a heart as strong as his fists.', colors:['#be5964','#e8bb7e','#29385f'], hair:'#392532', aura:'#ff7184'}
  ];
  const levels = {easy:{label:'ROOKIE',hint:'A friendly first fight.',health:78,damage:.65,think:1.05,pace:.55},normal:{label:'WARRIOR',hint:'A worthy warm-up.',health:100,damage:1,think:.72,pace:.78},hard:{label:'LEGEND',hint:'Only the strongest survive.',health:120,damage:1.32,think:.43,pace:1}};
  const $ = id => document.getElementById(id);
  const canvas = $('arena'), ctx = canvas.getContext('2d');
  let selected = 0, opponent = 1, difficulty = 'normal', running = false, ended = false, last = 0, elapsed = 0, remaining = 99, animFrame;
  let player, enemy, projectiles = [], particles = [], keys = new Set(), held = new Set(), combo = 0, comboTimer = 0, soundOn = true, audioCtx;
  let W = 960, H = 500, dpr = 1;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const rand=(a,b)=>a+Math.random()*(b-a);
  function fighterArt(c, x, y, scale, facing, pose=0, aura=false, palette=roster[0], time=0) {
    c.save(); c.translate(x,y); c.scale(scale*facing,scale); const p=pose||0;
    if(aura){const pulse=.75+Math.sin(time*8)*.13,g=c.createRadialGradient(0,-62,9,0,-62,83*pulse);g.addColorStop(0,palette.aura+'36');g.addColorStop(.55,palette.aura+'19');g.addColorStop(1,palette.aura+'00');c.fillStyle=g;c.beginPath();c.ellipse(0,-65,67*pulse,93*pulse,0,0,Math.PI*2);c.fill();}
    // boots and legs
    c.fillStyle='#242032'; c.beginPath();c.moveTo(-14,-38);c.lineTo(-14,-10);c.lineTo(-29,-3);c.quadraticCurveTo(-31,0,-25,2);c.lineTo(-7,1);c.lineTo(-3,-8);c.lineTo(3,-36);c.closePath();c.fill();
    c.beginPath();c.moveTo(5,-38);c.lineTo(8,-10);c.lineTo(3,-3);c.quadraticCurveTo(2,1,8,2);c.lineTo(28,1);c.quadraticCurveTo(32,-2,25,-6);c.lineTo(18,-12);c.lineTo(21,-38);c.closePath();c.fill();
    c.fillStyle=palette.colors[1];c.fillRect(-18,-16,13,5);c.fillRect(7,-16,13,5);
    // torso, gi and arms
    c.fillStyle=palette.colors[0];c.beginPath();c.moveTo(-17,-78);c.lineTo(-24,-69);c.lineTo(-18,-39);c.lineTo(19,-39);c.lineTo(24,-68);c.lineTo(15,-79);c.lineTo(0,-72);c.closePath();c.fill();
    c.fillStyle=palette.colors[1];c.beginPath();c.moveTo(-4,-73);c.lineTo(8,-79);c.lineTo(16,-71);c.lineTo(8,-62);c.lineTo(1,-68);c.lineTo(-1,-55);c.lineTo(-8,-61);c.closePath();c.fill();
    c.fillStyle=palette.colors[2];c.fillRect(-21,-47,42,5);c.fillStyle=palette.colors[1];c.fillRect(-5,-48,10,7);
    // back arm
    c.strokeStyle=palette.colors[0];c.lineWidth=10;c.lineCap='round';c.beginPath();c.moveTo(-16,-70);c.lineTo(-26,-55+p*4);c.lineTo(-23,-43+p*4);c.stroke();
    c.fillStyle=palette.colors[1];c.beginPath();c.ellipse(-23,-41+p*4,7,7,0,0,Math.PI*2);c.fill();
    // front arm punch pose
    c.strokeStyle=palette.colors[0];c.lineWidth=11;c.beginPath();c.moveTo(16,-69);c.lineTo(23+p*8,-60);c.lineTo(27+p*17,-53);c.stroke();
    c.fillStyle='#f0c89d';c.beginPath();c.ellipse(29+p*17,-51,8,7,0,0,Math.PI*2);c.fill();
    // neck and face
    c.fillStyle='#e6bd9a';c.fillRect(-5,-84,11,11);c.fillStyle='#ecc9a6';c.beginPath();c.ellipse(1,-95,15,17,0,0,Math.PI*2);c.fill();
    c.fillStyle=palette.hair;c.beginPath();c.moveTo(-14,-99);c.lineTo(-21,-113);c.lineTo(-9,-107);c.lineTo(-7,-122);c.lineTo(1,-110);c.lineTo(9,-124);c.lineTo(11,-108);c.lineTo(22,-115);c.lineTo(17,-99);c.lineTo(13,-104);c.lineTo(-11,-104);c.closePath();c.fill();
    c.fillStyle='#322532';c.beginPath();c.moveTo(5,-94);c.lineTo(12,-92);c.lineTo(7,-90);c.fill();c.fillStyle='#fff0d4';c.fillRect(7,-94,3,2);
    // aura sparks
    if(aura){for(let i=0;i<5;i++){let yy=-20-((time*50+i*29)%105),xx=Math.sin(time*6+i*3)*38;c.globalAlpha=.5+Math.sin(time*12+i)*.3;c.fillStyle=palette.aura;c.beginPath();c.moveTo(xx,yy);c.lineTo(xx+3,yy-9);c.lineTo(xx+1,yy+1);c.lineTo(xx-3,yy+8);c.fill();}c.globalAlpha=1;}
    c.restore();
  }
  function makeArtCanvas(container,palette,size=150){let can=document.createElement('canvas');can.width=can.height=220;container.innerHTML='';container.appendChild(can);let c=can.getContext('2d');fighterArt(c,110,197,1.26,-1,0,true,palette,.3);}
  function setupRoster(){const host=$('roster');host.innerHTML='';roster.forEach((f,i)=>{const b=document.createElement('button');b.className='fighter-card'+(i===selected?' selected':'');b.setAttribute('aria-label','Choose '+f.name);const can=document.createElement('canvas');can.width=180;can.height=220;b.append(can);const n=document.createElement('span');n.className='fighter-card-num';n.textContent='0'+(i+1);b.append(n);const label=document.createElement('span');label.className='fighter-card-name';label.textContent=f.name;b.append(label);fighterArt(can.getContext('2d'),90,196,1.03,-1,0,true,f,.4);b.onclick=()=>{selected=i;if(opponent===selected)opponent=(selected+1)%roster.length;updateSetup()};host.append(b)});updateSetup();}
  function updateSetup(){[...$('roster').children].forEach((el,i)=>el.classList.toggle('selected',i===selected));const f=roster[selected];$('fighterName').textContent=f.name;$('fighterRole').textContent=f.title;$('fighterDesc').textContent=f.desc;$('fighterStats').innerHTML=['POWER','SPEED','KI'].map((n,i)=>`<div class="stat-row">${n}<div class="stat-track"><i style="width:${f.stats[i]*10}%"></i></div></div>`).join('');makeArtCanvas($('selectedPortrait'),f,90);updateOpponent();}
