document.querySelectorAll('[data-action]').forEach(btn=>{const a=btn.dataset.action;btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);held.add(a);if(a==='attack'||a==='blast'||a==='jump')keys.add(a)});const release=e=>{if(e)e.preventDefault();held.delete(a);if(a==='block')keys.delete(a);if(a==='attack'||a==='blast'||a==='jump')keys.delete(a)};btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',release)});
function announce(text){$('announce').innerHTML=`<span>${text}</span>`;$('announce').className='announce show';setTimeout(()=>$('announce').classList.remove('show'),1050)}
function burst(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-190,190),vy:rand(-200,100),life:rand(.22,.58),max:.58,color,size:rand(2,5)})}
function attack(f,target,isPlayer,kind){if(f.stun>0)return;if(kind==='blast'){if(f.energy<20||f.blast>.15)return;f.energy-=20;f.blast=.42;const dir=f.facing;projectiles.push({x:f.x+dir*31,y:H-112-f.y,dir,owner:isPlayer?'player':'enemy',damage:isPlayer?11:12*levels[difficulty].damage,speed:560,color:(isPlayer?roster[selected]:roster[opponent]).aura,life:2});sound('blast');burst(f.x+dir*28,H-115-f.y,(isPlayer?roster[selected]:roster[opponent]).aura,5);return}if(f.attack>.12)return;f.attack=.33;f.pose=1;}
function damage(target,amount,fromX,owner){if(target.guard){amount*=.22;target.energy=Math.min(100,target.energy+8);sound('guard');burst(target.x,H-106-target.y,'#9ccfff',5)}else{target.health=Math.max(0,target.health-amount);target.stun=.19;target.hitFlash=.13;target.vx=(target.x>fromX?1:-1)*145;target.energy=Math.min(100,target.energy+5);sound('hit');burst(target.x,H-105-target.y,owner==='player'?roster[selected].aura:roster[opponent].aura,10);if(owner==='player'){combo++;comboTimer=1.5;if(combo>=3)announce('COMBO × '+combo)}}}
function updateFighter(f,dt){f.stun=Math.max(0,f.stun-dt);f.attack=Math.max(0,f.attack-dt);f.blast=Math.max(0,f.blast-dt);f.hitFlash=Math.max(0,f.hitFlash-dt);f.vy+=680*dt;f.y+=f.vy*dt;if(f.y>=0){f.y=0;f.vy=0;f.grounded=true}f.x+=f.vx*dt;f.vx*=Math.pow(.001,dt);f.x=clamp(f.x,65,895)}
function updateAI(dt){const lev=levels[difficulty],dx=player.x-enemy.x,d=Math.abs(dx);enemy.facing=dx<0?-1:1;enemy.ai-=dt;if(enemy.ai<=0&&enemy.stun<=0){enemy.ai=lev.think*rand(.72,1.3);enemy.guard=false;if(player.attack>0&&d<125&&Math.random()>.3)enemy.guard=true;else if(d>112){if(Math.random()<.14&&d<300&&enemy.energy>30)attack(enemy,player,false,'blast');else enemy.vx=Math.sign(dx)*150*lev.pace}else if(d<70&&Math.random()<.18)enemy.vx=-Math.sign(dx)*120;else if(Math.random()<.68)attack(enemy,player,false,'attack');else enemy.guard=true;if(enemy.grounded&&d>145&&Math.random()<.12)enemy.vy=-310;}
  if(d>150&&enemy.energy<38)enemy.energy=Math.min(40,enemy.energy+dt*4);else enemy.energy=Math.min(100,enemy.energy+dt*1.1);
  if(enemy.attack>.1&&d<94&&enemy.grounded&&Math.random()>.1){if(!enemy.didHit){enemy.didHit=true;damage(player,7.5*lev.damage,enemy.x,'enemy')}}else if(enemy.attack<=.1)enemy.didHit=false;
}
function update(dt){elapsed+=dt;remaining=Math.max(0,99-Math.floor(elapsed));player.facing=player.x<enemy.x?1:-1;enemy.facing=enemy.x<player.x?1:-1;player.guard=keys.has('block')||held.has('block');if(player.stun<=0){let move=(keys.has('right')?1:0)-(keys.has('left')?1:0);player.vx=move*235;if(move)player.guard=false;if((keys.has('jump')||held.has('jump'))&&player.grounded){player.vy=-340;player.grounded=false;keys.delete('jump')}if(keys.has('attack')){attack(player,enemy,true,'attack');keys.delete('attack')}if(keys.has('blast')){attack(player,enemy,true,'blast');keys.delete('blast')}}
  player.energy=Math.min(100,player.energy+dt*(player.guard?2.3:1.5));updateAI(dt);updateFighter(player,dt);updateFighter(enemy,dt);
  let distance=Math.abs(player.x-enemy.x);if(player.attack>.10&&player.attack<.27&&distance<95&&!player.didHit){player.didHit=true;damage(enemy,9,player.x,'player')}if(player.attack<=.10)player.didHit=false;
  if(enemy.attack>.1&&distance<95&&!enemy.didHit){enemy.didHit=true;damage(player,7.5*levels[difficulty].damage,enemy.x,'enemy')}if(enemy.attack<=.1)enemy.didHit=false;
  for(let i=projectiles.length-1;i>=0;i--){let p=projectiles[i];p.x+=p.dir*p.speed*dt;p.life-=dt;let tgt=p.owner==='player'?enemy:player;if(Math.abs(p.x-tgt.x)<29&&Math.abs((H-p.y)-(H-110-tgt.y))<85){damage(tgt,p.damage,p.x,p.owner);burst(p.x,p.y,p.color,12);projectiles.splice(i,1)}else if(p.life<=0||p.x<0||p.x>W)projectiles.splice(i,1)}
  for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}if(comboTimer>0)comboTimer-=dt;else combo=0;
  $('playerHealth').style.width=player.health+'%';$('enemyHealth').style.width=clamp(enemy.health/levels[difficulty].health*100,0,100)+'%';$('playerEnergy').style.width=player.energy+'%';$('enemyEnergy').style.width=enemy.energy+'%';$('timerText').textContent=String(remaining).padStart(2,'0');$('comboReadout').textContent=combo>1&&comboTimer>0?`${combo} HIT COMBO!`:'';
  if(player.health<=0||enemy.health<=0||remaining<=0){finish(enemy.health<=0||player.health>enemy.health/levels[difficulty].health*100);}
}
function finish(win){if(ended)return;ended=true;running=false;$('resultTitle').textContent=win?'VICTORY':'DEFEAT';$('resultTitle').style.color=win?'#ffd28a':'#ff8290';$('resultText').textContent=win?`${roster[selected].name} stands victorious. The galaxy will remember this day.`:'The arena has a new champion. Train hard and fight again.';$('resultModal').classList.remove('hidden');sound(win?'win':'lose')}
